test('renderInvoiceText shows voucher when present', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const withVoucher = applyVoucher(inv, { code: 'SAVE10', amount: 1000 }).value;
  const text = renderInvoiceText(withVoucher);

  assert.ok(text.includes('Voucher:'));
  assert.ok(text.includes('-€10.00'));
});

test('renderInvoiceText hides voucher when amount is 0', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const text = renderInvoiceText(inv);

  assert.ok(!text.includes('Voucher:'));
});

test('renderInvoiceText shows due date when present', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET30',
  }).value;

  const issued = issueInvoice(inv, []).value;
  const text = renderInvoiceText(issued);

  assert.ok(text.includes('Due:'));
  assert.ok(text.includes('2024-03-16'));
});

test('renderInvoiceText hides due date for draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const text = renderInvoiceText(draft);

  assert.ok(!text.includes('Due:'));
});

test('renderInvoiceText shows paid amount when payments exist', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const withPayment = recordPayment(issued, { amount: 5000, date: '2024-02-20' }).value;
  const text = renderInvoiceText(withPayment);

  assert.ok(text.includes('Paid:'));
  assert.ok(text.includes('€50.00'));
});

test('renderInvoiceText shows multiple payments summed', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const after1st = recordPayment(issued, { amount: 5000, date: '2024-02-20' }).value;
  const after2nd = recordPayment(after1st, { amount: 3000, date: '2024-02-25' }).value;
  const text = renderInvoiceText(after2nd);

  assert.ok(text.includes('Paid:'));
  assert.ok(text.includes('€80.00'));
});

test('renderInvoiceText hides paid when no payments', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const text = renderInvoiceText(issued);

  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText with voucher and due date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;

  const withVoucher = applyVoucher(inv, { code: 'SAVE', amount: 1000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const text = renderInvoiceText(issued);

  assert.ok(text.includes('Voucher:'));
  assert.ok(text.includes('Due:'));
  assert.ok(text.includes('2024-02-29'));
});

test('renderInvoiceText with all optional fields', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET30',
  }).value;

  const withVoucher = applyVoucher(inv, { code: 'SAVE', amount: 1000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const withPayment = recordPayment(issued, { amount: 3000, date: '2024-02-20' }).value;
  const text = renderInvoiceText(withPayment);

  assert.ok(text.includes('Voucher:'));
  assert.ok(text.includes('Due:'));
  assert.ok(text.includes('Paid:'));
});

test('renderInvoiceText voucher line before total', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const withVoucher = applyVoucher(inv, { code: 'SAVE', amount: 1000 }).value;
  const text = renderInvoiceText(withVoucher);
  const lines = text.split('\n');

  const voucherIdx = lines.findIndex((l) => l.startsWith('Voucher:'));
  const totalIdx = lines.findIndex((l) => l.startsWith('Total:'));

  assert.ok(voucherIdx >= 0);
  assert.ok(totalIdx >= 0);
  assert.ok(voucherIdx < totalIdx);
});

test('renderInvoiceText due date after total', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET30',
  }).value;

  const issued = issueInvoice(inv, []).value;
  const text = renderInvoiceText(issued);
  const lines = text.split('\n');

  const totalIdx = lines.findIndex((l) => l.startsWith('Total:'));
  const dueIdx = lines.findIndex((l) => l.startsWith('Due:'));

  assert.ok(totalIdx >= 0);
  assert.ok(dueIdx >= 0);
  assert.ok(dueIdx > totalIdx);
});

