import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { formatEuros } from '../src/money.js';

test('renderInvoiceText shows DRAFT for draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
});

test('renderInvoiceText shows invoice number when issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const text = renderInvoiceText(issued);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2024-0001');
});

test('renderInvoiceText shows customer ID', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[1], 'Customer: C-003');
});

test('renderInvoiceText formats a single line item', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '10 x Development (hour) @ €95.00 = €950.00');
});

test('renderInvoiceText formats multiple line items', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '10 x Development (hour) @ €95.00 = €950.00');
  assert.equal(lines[3], '1 x Logo package @ €1,200.00 = €1,200.00');
});

test('renderInvoiceText shows total on last line', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  const subtotal = 95000 + 120000;
  const devVAT = Math.round((95000 * 21) / 100);
  const logoVAT = Math.round((120000 * 21) / 100);
  const totalAmount = subtotal + devVAT + logoVAT;

  const totalLine = lines.find((l) => l.startsWith('Total:'));
  assert.ok(totalLine);
  assert.ok(totalLine.includes(formatEuros(totalAmount)));
});

test('renderInvoiceText formats amounts in euros', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'STICKER', qty: 100 },
      { sku: 'HOST-MONTH', qty: 12 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '100 x Sticker sheet @ €0.50 = €50.00');
  assert.equal(lines[3], '12 x Website hosting (month) @ €15.00 = €180.00');

  const totalLine = lines.find((l) => l.startsWith('Total:'));
  assert.ok(totalLine);

  const subtotal = 5000 + 18000;
  const vat = Math.round((subtotal * 21) / 100);
  const total = subtotal + vat;
  assert.ok(totalLine.includes(formatEuros(total)));
});

test('renderInvoiceText shows complete invoice with issued number', () => {
  const invoice = createInvoice({
    customerId: 'C-005',
    issueDate: '2024-03-20',
    lines: [
      { sku: 'COPY-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 5 },
    ],
  }).value;

  const issued = issueInvoice(invoice, ['INV-2024-0001']).value;
  const text = renderInvoiceText(issued);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2024-0002');
  assert.equal(lines[1], 'Customer: C-005');
  assert.ok(lines[2].includes('(2.5% discount: -€12.00)'));
  assert.ok(lines[3].includes('(2.5% discount: -€1.22)'));
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Discount:'));
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Total:'));
});

test('renderInvoiceText renders as single string with newlines', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.equal(typeof text, 'string');
  assert.ok(text.includes('\n'));
  const lines = text.split('\n');

  assert.ok(text.includes('DRAFT'));
  assert.ok(text.includes('Customer:'));
  assert.ok(text.includes('Development'));
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Total:'));
});

test('renderInvoiceText shows discount on line item', () => {
