  const devTotal = 5 * 9500;
  const devVAT = Math.round((devTotal * 21) / 100);
  const printTotal = 50 * 37;
  const printVAT = Math.round((printTotal * 9) / 100);

  const vatLine = text.split('\n').find((l) => l.startsWith('VAT:'));
  assert.ok(vatLine);
  assert.ok(vatLine.includes('€'));
});

