import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { formatEuros } from '../src/money.js';

test('renderInvoiceText shows DRAFT for draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
});

test('renderInvoiceText shows invoice number when issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const text = renderInvoiceText(issued);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2024-0001');
});

test('renderInvoiceText shows customer ID', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[1], 'Customer: C-003');
});

test('renderInvoiceText formats a single line item', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '10 x Development (hour) @ €95.00 = €950.00');
});

test('renderInvoiceText formats multiple line items', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '10 x Development (hour) @ €95.00 = €950.00');
  assert.equal(lines[3], '1 x Logo package @ €1,200.00 = €1,200.00');
});

test('renderInvoiceText shows total on last line', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  const subtotal = 95000 + 120000;
  const devVAT = Math.round((95000 * 21) / 100);
  const logoVAT = Math.round((120000 * 21) / 100);
  const totalAmount = subtotal + devVAT + logoVAT;

  const totalLine = lines.find((l) => l.startsWith('Total:'));
  assert.ok(totalLine);
  assert.ok(totalLine.includes(formatEuros(totalAmount)));
});

test('renderInvoiceText formats amounts in euros', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'STICKER', qty: 100 },
      { sku: 'HOST-MONTH', qty: 12 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '100 x Sticker sheet @ €0.50 = €50.00');
  assert.equal(lines[3], '12 x Website hosting (month) @ €15.00 = €180.00');

  const totalLine = lines.find((l) => l.startsWith('Total:'));
  assert.ok(totalLine);

  const subtotal = 5000 + 18000;
  const vat = Math.round((subtotal * 21) / 100);
  const total = subtotal + vat;
  assert.ok(totalLine.includes(formatEuros(total)));
});

test('renderInvoiceText shows complete invoice with issued number', () => {
  const invoice = createInvoice({
    customerId: 'C-005',
    issueDate: '2024-03-20',
    lines: [
      { sku: 'COPY-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 5 },
    ],
  }).value;

  const issued = issueInvoice(invoice, ['INV-2024-0001']).value;
  const text = renderInvoiceText(issued);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2024-0002');
  assert.equal(lines[1], 'Customer: C-005');
  assert.ok(lines[2].includes('(2.5% discount: -€12.00)'));
  assert.ok(lines[3].includes('(2.5% discount: -€1.22)'));
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Discount:'));
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Total:'));
});

test('renderInvoiceText renders as single string with newlines', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert.equal(typeof text, 'string');
  assert.ok(text.includes('\n'));
  const lines = text.split('\n');

  assert.ok(text.includes('DRAFT'));
  assert.ok(text.includes('Customer:'));
  assert.ok(text.includes('Development'));
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Total:'));
});

test('renderInvoiceText shows discount on line item', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines[2].includes('(10% discount: -€95.00)'));
});

test('renderInvoiceText shows decimal discount percentage', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 12.5 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines[2].includes('(12.5% discount: -€118.75)'));
});

test('renderInvoiceText shows subtotal and discount when discounts present', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines.some((line) => line.startsWith('Subtotal:')));
  assert.ok(lines.some((line) => line.startsWith('Discount:')));
  assert.ok(lines.some((line) => line.startsWith('Total:')));
});

test('renderInvoiceText formats discount line correctly', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.equal(lines[2], '10 x Development (hour) @ €95.00 = €950.00 (10% discount: -€95.00)');
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Discount: -€95.00'));
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Total:'));
});

test('renderInvoiceText does not show discount or subtotal when no discount and no VAT', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(!text.includes('Subtotal:'));
  assert.ok(!text.includes('Discount:'));
  assert.ok(!text.includes('VAT:'));
  assert.ok(lines.some((line) => line.startsWith('Total:')));
  assert.equal(lines.length, 4);
});

test('renderInvoiceText shows multiple lines with mixed discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-005',
    issueDate: '2024-03-20',
    lines: [
      { sku: 'COPY-HOUR', qty: 8, discountPercent: 5 },
      { sku: 'ICON-SET', qty: 5, discountPercent: 0 },
      { sku: 'DOMAIN-YEAR', qty: 2, discountPercent: 15 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines[2].includes('(5% discount: -€24.00)'));
  assert.ok(!lines[3].includes('discount'));
  assert.ok(lines[4].includes('(15% discount: -€3.90)'));
  assert.ok(lines.some((line) => line.startsWith('Subtotal:')));
  assert.ok(lines.some((line) => line.startsWith('Discount:')));
});

test('renderInvoiceText shows tier discount applied automatically', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines[2].includes('(5% discount: -€47.50)'));
});

test('renderInvoiceText shows silver tier discount', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines[2].includes('(2.5% discount: -€23.75)'));
});

test('renderInvoiceText shows standard tier (no discount)', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(!text.includes('discount'));
  assert.equal(lines[2], '10 x Development (hour) @ €95.00 = €950.00');
});

test('renderInvoiceText shows VAT line when VAT is present', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Total:'));
});

test('renderInvoiceText shows correct VAT amount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  const devTotal = 10 * 9500;
  const vat = Math.round((devTotal * 21) / 100);

  const vatLine = lines.find((l) => l.startsWith('VAT:'));
  assert.ok(vatLine.includes(formatEuros(vat)));
});

test('renderInvoiceText does not show VAT line when VAT is 0', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);

  assert.ok(!text.includes('VAT:'));
  assert.ok(!text.includes('Subtotal:'));
});

test('renderInvoiceText shows VAT with discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Discount:'));
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Total:'));

  const devTotal = 10 * 9500;
  const discount = Math.round((devTotal * 10) / 100);
  const afterDiscount = devTotal - discount;
  const vat = Math.round((afterDiscount * 21) / 100);

  const subtotalLine = lines.find((l) => l.startsWith('Subtotal:'));
  const discountLine = lines.find((l) => l.startsWith('Discount:'));
  const vatLine = lines.find((l) => l.startsWith('VAT:'));
  const totalLine = lines.find((l) => l.startsWith('Total:'));

  assert.ok(subtotalLine.includes(formatEuros(devTotal)));
  assert.ok(discountLine.includes(formatEuros(discount)));
  assert.ok(vatLine.includes(formatEuros(vat)));
  assert.ok(totalLine.includes(formatEuros(devTotal - discount + vat)));
});

test('renderInvoiceText shows mixed VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'PRINT-A4', qty: 50 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);

  assert.ok(text.includes('VAT:'));

  const devTotal = 5 * 9500;
  const devVAT = Math.round((devTotal * 21) / 100);
  const printTotal = 50 * 37;
  const printVAT = Math.round((printTotal * 9) / 100);

  const vatLine = text.split('\n').find((l) => l.startsWith('VAT:'));
  assert.ok(vatLine);
  assert.ok(vatLine.includes('€'));
});

test('renderInvoiceText shows voucher when present', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const withVoucher = applyVoucher(inv, { code: 'SAVE10', amount: 1000 }).value;
  const text = renderInvoiceText(withVoucher);

  assert.ok(text.includes('Voucher:'));
  assert.ok(text.includes('-€10.00'));
});

test('renderInvoiceText hides voucher when amount is 0', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const text = renderInvoiceText(inv);

  assert.ok(!text.includes('Voucher:'));
});

test('renderInvoiceText shows due date when present', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET30',
  }).value;

  const issued = issueInvoice(inv, []).value;
  const text = renderInvoiceText(issued);

  assert.ok(text.includes('Due:'));
  assert.ok(text.includes('2024-03-16'));
});

test('renderInvoiceText hides due date for draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const text = renderInvoiceText(draft);

  assert.ok(!text.includes('Due:'));
});

test('renderInvoiceText shows paid amount when payments exist', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const withPayment = recordPayment(issued, { amount: 5000, date: '2024-02-20' }).value;
  const text = renderInvoiceText(withPayment);

  assert.ok(text.includes('Paid:'));
  assert.ok(text.includes('€50.00'));
});

test('renderInvoiceText shows multiple payments summed', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const after1st = recordPayment(issued, { amount: 5000, date: '2024-02-20' }).value;
  const after2nd = recordPayment(after1st, { amount: 3000, date: '2024-02-25' }).value;
  const text = renderInvoiceText(after2nd);

  assert.ok(text.includes('Paid:'));
  assert.ok(text.includes('€80.00'));
});

test('renderInvoiceText hides paid when no payments', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const text = renderInvoiceText(issued);

  assert.ok(!text.includes('Paid:'));
});

test('renderInvoiceText with voucher and due date', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  }).value;

  const withVoucher = applyVoucher(inv, { code: 'SAVE', amount: 1000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const text = renderInvoiceText(issued);

  assert.ok(text.includes('Voucher:'));
  assert.ok(text.includes('Due:'));
  assert.ok(text.includes('2024-02-29'));
});

test('renderInvoiceText with all optional fields', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET30',
  }).value;

  const withVoucher = applyVoucher(inv, { code: 'SAVE', amount: 1000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const withPayment = recordPayment(issued, { amount: 3000, date: '2024-02-20' }).value;
  const text = renderInvoiceText(withPayment);

  assert.ok(text.includes('Voucher:'));
  assert.ok(text.includes('Due:'));
  assert.ok(text.includes('Paid:'));
});

test('renderInvoiceText voucher line before total', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const withVoucher = applyVoucher(inv, { code: 'SAVE', amount: 1000 }).value;
  const text = renderInvoiceText(withVoucher);
  const lines = text.split('\n');

  const voucherIdx = lines.findIndex((l) => l.startsWith('Voucher:'));
  const totalIdx = lines.findIndex((l) => l.startsWith('Total:'));

  assert.ok(voucherIdx >= 0);
  assert.ok(totalIdx >= 0);
  assert.ok(voucherIdx < totalIdx);
});

test('renderInvoiceText due date after total', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET30',
  }).value;

  const issued = issueInvoice(inv, []).value;
  const text = renderInvoiceText(issued);
  const lines = text.split('\n');

  const totalIdx = lines.findIndex((l) => l.startsWith('Total:'));
  const dueIdx = lines.findIndex((l) => l.startsWith('Due:'));

  assert.ok(totalIdx >= 0);
  assert.ok(dueIdx >= 0);
  assert.ok(dueIdx > totalIdx);
});

