test('renderInvoiceText shows VAT with discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(text.includes('Subtotal:'));
  assert.ok(text.includes('Discount:'));
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Total:'));

  const devTotal = 10 * 9500;
  const discount = Math.round((devTotal * 10) / 100);
  const afterDiscount = devTotal - discount;
  const vat = Math.round((afterDiscount * 21) / 100);

  const subtotalLine = lines.find((l) => l.startsWith('Subtotal:'));
  const discountLine = lines.find((l) => l.startsWith('Discount:'));
  const vatLine = lines.find((l) => l.startsWith('VAT:'));
  const totalLine = lines.find((l) => l.startsWith('Total:'));

  assert.ok(subtotalLine.includes(formatEuros(devTotal)));
  assert.ok(discountLine.includes(formatEuros(discount)));
  assert.ok(vatLine.includes(formatEuros(vat)));
  assert.ok(totalLine.includes(formatEuros(devTotal - discount + vat)));
